import {createHeritagePages} from "./heritage-pages.mjs";
import {loadHeritageContext,loadHeritageImageDimensions} from "./heritage-context.mjs";

const root = new URL("..", import.meta.url).pathname.replace(/^\/(.:)/, "$1");
const argMode = process.argv.find(value => value.startsWith("--mode="))?.split("=")[1];
const mode = argMode || process.env.APP_MODE || "production";
if (!["production", "studio", "demo"].includes(mode)) throw new Error(`Unknown APP_MODE: ${mode}`);
const studioMode = mode !== "production";
const defaultOutputRoot = join(root, studioMode ? "dist-demo" : "dist-production");
const outputRoot = process.env.VIRSAPUR_OUTPUT_DIR ? resolve(process.env.VIRSAPUR_OUTPUT_DIR) : defaultOutputRoot;
const outputRelative = relative(resolve(root), outputRoot);
if (outputRelative.startsWith("..") || isAbsolute(outputRelative)) throw new Error("Build output must stay inside the Virsapur project.");
const source = await loadBuildContent({ root, appMode: mode });
const temporaryPhotography = JSON.parse(await readFile(join(root, "content", "data", "temporary-image-overrides.json"), "utf8"));
const { site, homepage, archiveCategories: archiveCategoriesBase, collaborators: collaboratorsBase, programmes: programmesBase, stories: storiesBase, projects: projectsBase, events: eventsBase, people: peopleBase, testimonials: testimonialsBase, heritagePlaces: heritagePlacesBase } = source;
const existingFixtures = studioMode ? JSON.parse(await readFile(join(root, "content", "fixtures", "demo.json"), "utf8")) : { stories: [], projects: [], events: [] };
const relationshipFixtures = studioMode ? JSON.parse(await readFile(join(root,"content","fixtures","heritage-interconnection.json"),"utf8")) : {};
const fixtures = Object.fromEntries(["stories","projects","programmes","events"].map(key=>[key,[...(existingFixtures[key]||[]),...(relationshipFixtures[key]||[])]]));
const visible = records => studioMode ? records : records.filter(item => item.status === "published" && !item.demo);
const programmes = visible([...fixtures.programmes,...programmesBase]);
const archiveCategories = visible(archiveCategoriesBase).sort((a,b)=>(a.sortOrder??999)-(b.sortOrder??999));
const collaborators = visible(collaboratorsBase).sort((a,b)=>(a.sortOrder??999)-(b.sortOrder??999));
const stories = visible([...fixtures.stories, ...storiesBase]);
const projects = visible([...fixtures.projects, ...projectsBase]);
const events = visible([...fixtures.events, ...eventsBase]);
const people = visible(peopleBase);
const testimonials = visible(testimonialsBase);
const preparedHeritage = await prepareHeritageRecords(root, visible(heritagePlacesBase));
const heritagePlaces = preparedHeritage.records;
const atlasScopeMedia = JSON.parse(await readFile(join(root,"content/data/atlas-scope-media.json"),"utf8"));
const siteOrigin = (process.env.SITE_ORIGIN || site.productionDomain || site.defaultSiteOrigin || "").replace(/\/+$/, "");
const routeManifest = [];

if (!studioMode && !siteOrigin) throw new Error("Production build blocked: production domain is missing.");
if (!studioMode && process.env.PAYMENT_MODE && process.env.PAYMENT_MODE !== "disabled") throw new Error("Production build blocked: PAYMENT_MODE must be disabled.");
if (!studioMode && JSON.stringify({ programmes, stories, projects, events }).includes('"demo":true')) throw new Error("Production build blocked: demo fixture content detected.");
for (const group of [programmesBase, storiesBase, projectsBase, eventsBase, archiveCategoriesBase]) {
  const slugs = new Set();
  for (const item of group) {
    if (!item.slug) continue;
    if (slugs.has(item.slug)) throw new Error(`Duplicate slug: ${item.slug}`);
    slugs.add(item.slug);
  }
}
for (const item of [...programmesBase, ...storiesBase, ...projectsBase, ...eventsBase].filter(record => record.status === "published")) {
  const image = item.featuredImage?.src || item.featuredImage?.mediaId || item.featuredImage?.storage || item.image?.src || item.image?.mediaId || item.image?.storage;
  const required = item.type === "programme" ? [item.title, item.slug, item.summary, item.body, image, item.seo?.title, item.seo?.description]
    : item.type === "story" ? [item.title, item.slug, item.summary, item.body?.length, item.primaryCategoryId, item.categoryIds?.length, image, item.featuredImage?.alt, item.seo?.title, item.seo?.description]
    : item.type === "project" ? [item.title, item.slug, item.summary, item.body?.length, image, item.seo?.title, item.seo?.description]
    : [item.programmeId, item.start, item.registrationState, item.location];
  if (required.some(value => !value)) throw new Error(`Published ${item.type || "record"} ${item.id} is incomplete.`);
}
for (const item of archiveCategoriesBase.filter(record => record.status === "published")) {
  const required=[item.title,item.slug,item.summary,item.description,item.featuredImage?.src,item.featuredImage?.alt,item.seo?.title,item.seo?.description];
  if(required.some(value=>!value))throw new Error(`Published Archive Category ${item.id} is incomplete.`);
}

const relationErrors = [...storiesBase,...projectsBase,...programmesBase,...eventsBase,...fixtures.stories,...fixtures.projects,...fixtures.programmes,...fixtures.events].flatMap(record=>validateHeritageIds(record,heritagePlacesBase));
if(relationErrors.length) throw new Error(relationErrors.join("\n"));
const placeSlugs = heritagePlaces.filter(isEligibleHeritagePlace).map(record=>record.slug);
if(new Set(placeSlugs).size !== placeSlugs.length) throw new Error("Duplicate Heritage Place slug.");
if(stories.some(record=>record.slug==="place")) throw new Error("Story slug 'place' conflicts with the Heritage Place route namespace.");
await rm(outputRoot, { recursive: true, force: true });
await mkdir(outputRoot, { recursive: true });
if (!studioMode && isProductionCmsEnabled() && (process.env.CMS_DATA_MODE || "local") === "production") await materializePrivateMedia(source, outputRoot);
const esc = (value = "") => String(value).replace(/[&<>\"]/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[char]);
const depth = route => route.split("/").filter(Boolean).length;
const prefix = route => "../".repeat(depth(route));
const href = routeHref;
const asset = (route, path) => `${prefix(route)}${path}`;
const canonical = route => `${siteOrigin || "http://127.0.0.1:4173"}${route === "/" ? "/" : route}`;
const phoneHref = String(site.phone || "").replace(/[^+\d]/g, "");
const mediaDims = { "archive-anarkali":[800,600],"archive-architecture":[1200,628],"archive-gurdwara":[639,426],"archive-katas":[640,379],"archive-lanes":[726,387],"archive-priest-king":[590,388],"archive-wells":[640,404],"founder-ahmad":[1600,1200],"founder-altamash":[787,591],"fresco-room":[1153,2048],"fresco-strip":[1035,320],"hero-badshahi":[1918,1080],"logo-full-slate":[1289,781],"logo-full-white":[1289,781],"pillar-red":[1153,2048],"pillar-white":[1153,2048],"project-1":[1920,1080],"project-2":[1920,1080],"temple-angle":[1153,2048],"temple-distant":[1153,2048],"temple-entrance":[1153,2048],"temple-shadow":[1153,2048] };
const mediaById = new Map((source.media || []).map(item => [item.id, item]));
const temporaryImages = temporaryPhotography.images || {};
const temporaryPlacements = temporaryPhotography.placements || {};
const visualImage = (placement, fallback) => temporaryImages[temporaryPlacements[placement]] || fallback;
const recordVisualImage = item => visualImage(item.id, item.featuredImage || item.image);
const imageRecord = value => {
  const linked = typeof value === "string" ? mediaById.get(value) : mediaById.get(value?.mediaId);
  const item = linked || (typeof value === "string" ? { src: value } : (value || site.defaultSeoImage));
  const stem = item.optimizedStem || item.src.replace(/^assets\//, "").replace(/\.[^.]+$/, "").replace(/_/g, "-");
  const [width, height] = mediaDims[stem] || [item.width || 1280, item.height || 720];
  return { ...item, optimizedStem: stem, width, height };
};
const optimizedPath = (value, target = 1280) => { const item = imageRecord(value); if(item.derivatives)return target<=640?item.derivatives.webp640:item.derivatives.webp1280; return `assets/optimized/${item.optimizedStem}-${Math.min(item.width, target)}.webp`; };
const absoluteImage = value => { const path=optimizedPath(value); return /^https?:\/\//.test(path)?path:`${siteOrigin}/${path}`; };
function picture(route, value, options = {}) {
  const item = imageRecord(value); const widths = [...new Set([Math.min(item.width,640),Math.min(item.width,1280)])];
  const position = `${item.focalX ?? 50}% ${item.focalY ?? 50}%`;
  const external = item.derivatives;
  const mediaPath = path => /^https?:\/\//.test(path) ? path : asset(route, path);
  const srcset = external ? `${mediaPath(external.webp640)} 640w, ${mediaPath(external.webp1280)} 1280w` : widths.map(w => `${asset(route, `assets/optimized/${item.optimizedStem}-${w}.webp`)} ${w}w`).join(", ");
  const src = external ? mediaPath(external.webp1280) : asset(route, `assets/optimized/${item.optimizedStem}-${widths.at(-1)}.webp`);
  return `<picture${options.className ? ` class="${options.className}"` : ""}><source type="image/webp" srcset="${srcset}" sizes="${options.sizes || "(max-width:760px) 100vw,50vw"}"><img src="${src}" width="${item.width}" height="${item.height}" alt="${options.decorative ? "" : esc(item.alt || "")}" loading="${options.eager ? "eager" : "lazy"}" decoding="async" style="object-position:${position}"${options.eager ? ' fetchpriority="high"' : ""}></picture>`;
}
const panelImageClass = value => {
  const image = imageRecord(value);
  const ratio = image.width / image.height;
  return ratio >= 2 ? "panoramic" : ratio >= 1.12 ? "landscape" : ratio <= .86 ? "portrait" : "square";
};
const badge = item => studioMode && item.demo ? '<span class="demo-badge">DEMO</span>' : studioMode && item.status !== "published" ? `<span class="status-badge">${esc(item.status)}</span>` : "";
const navItems = site.navigation.filter(item => item.visible !== false && (item.id !== "whats-on" || events.length));
const categoryById = new Map(archiveCategories.map(item=>[item.id,item]));
const primaryCategory = item => categoryById.get(item.primaryCategoryId);
const storyCategoryLabel = item => primaryCategory(item)?.title || item.category || "Story";
const storyCategorySearch = item => [...new Set([...(item.categoryIds||[]),...(item.categoryIds||[]).map(id=>categoryById.get(id)?.title),item.category].filter(Boolean))].join(" ");
const selectByIds = (records, ids=[]) => {
  const byId=new Map(records.map(item=>[item.id,item]));
  return [...new Set(ids)].map(id=>byId.get(id)).filter(Boolean);
};
function header(route, active) {
  return `<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="${href(route,"/")}" aria-label="Virsapur home"><img src="${asset(route,optimizedPath("assets/logo_full_slate.png",640))}" width="1289" height="781" alt="Virsapur"></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation">${navItems.map(item => `<a href="${href(route,item.route)}"${active === item.id ? ' aria-current="page"' : ""}>${esc(item.label)}</a>`).join("")}</nav><a class="contact-link" href="${href(route,"/contact")}"${active === "contact" ? ' aria-current="page"' : ""}>Get in touch</a></header>`;
}
function footer(route) {
  return `<footer class="site-footer"><div class="footer-identity"><img src="${asset(route,optimizedPath("assets/logo_full_white.png",640))}" width="1289" height="781" alt="Virsapur"><p>${esc(site.purpose)}</p></div><div><p class="footer-label">Explore</p><nav aria-label="Footer navigation">${navItems.map(item => `<a href="${href(route,item.route)}">${esc(item.label)}</a>`).join("")}</nav></div><div class="footer-contact"><p class="footer-label">Connect</p><a href="${href(route,"/contact")}">Contact</a><a href="mailto:${esc(site.email)}">${esc(site.email)}</a>${site.phone ? `<a href="tel:${phoneHref}">${esc(site.phone)}</a>` : ""}<small>© ${new Date().getFullYear()} Virsapur</small></div></footer>`;
}
function shell({ route, active = "", title, description, main, status = "published", image = site.defaultSeoImage, schema = [] }) {
  const indexable = !studioMode && status === "published"; const social = imageRecord(image);
  const releaseMeta = process.env.CMS_CONTENT_VERSION ? `<meta name="virsapur-content-version" content="${esc(process.env.CMS_CONTENT_VERSION)}">` : "";
  const graph = [{ "@type":"WebPage", name:title, description, url:canonical(route), isPartOf:{"@id":`${siteOrigin}/#website`} }, ...schema];
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${releaseMeta}<title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical(route)}"><meta name="robots" content="${indexable ? "index,follow,max-image-preview:large" : "noindex,nofollow"}"><meta property="og:locale" content="en_PK"><meta property="og:type" content="website"><meta property="og:site_name" content="${esc(site.name)}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical(route)}"><meta property="og:image" content="${absoluteImage(social)}"><meta property="og:image:alt" content="${esc(social.alt || title)}"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">${JSON.stringify({"@context":"https://schema.org","@graph":graph}).replace(/</g,"\\u003c")}</script><link rel="stylesheet" href="${asset(route,"styles.css?v=platform-v1")}"></head><body data-mode="${mode}" data-route="${route}" data-contact-connected="${String(site.integrations?.contact?.connected)}">${studioMode ? '<div class="dev-bar">VIRSAPUR DEV SANDBOX · DEMO CONTENT ENABLED</div>' : ""}${header(route,active)}<main id="main">${main}</main>${footer(route)}<script src="${asset(route,"app.js?v=platform-v1")}" defer></script></body></html>`;
}
function pageHero(route, { eyebrow, title, intro, image, alt, variant="editorial", supplement="" }) { return `<section class="page-hero page-hero--${esc(variant)}${image ? " has-image" : ""}"><div class="page-hero-copy"><p class="overline">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p>${esc(intro)}</p>${supplement}</div>${image ? picture(route,{...imageRecord(image),alt:alt || imageRecord(image).alt},{className:"page-hero-image",eager:true,sizes:"(max-width:820px) 100vw,48vw"}) : ""}</section>`; }
const cta = (route,title="Start a conversation about heritage.") => `<section class="page-cta"><p class="overline">Work with Virsapur</p><h2>${esc(title)}</h2><p>For programmes, research, education and cultural collaboration.</p><a class="button light" href="${href(route,"/contact")}">Contact Virsapur</a></section>`;
function crumbs(route, items) { const schema={"@type":"BreadcrumbList",itemListElement:items.map((item,i)=>({"@type":"ListItem",position:i+1,name:item.label,item:canonical(item.path||route)}))}; return { html:`<nav class="breadcrumb" aria-label="Breadcrumb">${items.map(item=>item.path?`<a href="${href(route,item.path)}">${esc(item.label)}</a><span aria-hidden="true">›</span>`:`<span aria-current="page">${esc(item.label)}</span>`).join("")}</nav>`, schema }; }
function editorialPanel(route,item,{kind=item.type||"programme",variant="portrait",action,link,extra=""}={}) {
  const base=kind==="story"?"/archives/":kind==="project"?"/projects/":"/service/";
  const target=link||`${base}${item.slug}`;
  const date=item.publishedAt?new Date(item.publishedAt).toLocaleDateString("en-PK",{day:"numeric",month:"short",year:"numeric"}):"";
  const categoryLabel=kind==="story"?storyCategoryLabel(item):item.category||item.kind||kind;
  const meta=[categoryLabel,item.location].filter(Boolean).join(" · ");
  const attributes=`data-record data-title="${esc(item.title.toLowerCase())}" data-category="${esc(kind==="story"?storyCategorySearch(item):categoryLabel)}" data-province="${esc(item.province||"")}" data-district="${esc(item.district||"")}" data-type="${esc(kind)}"`;
  const imageValue=recordVisualImage(item);
  const image=picture(route,imageValue,{className:"editorial-panel-image",sizes:"(max-width:700px) 86vw,(max-width:1000px) 44vw,30vw"});
  const body=`<div class="editorial-panel-body">${badge(item)}<p class="overline">${esc(meta)}</p><h3>${esc(item.title)}</h3>${item.summary?`<p class="editorial-panel-summary">${esc(item.summary)}</p>`:""}${date?`<p class="editorial-panel-facts">${esc(date)}</p>`:""}${extra}<span class="editorial-panel-action">${esc(action||(kind==="story"?"Read story":"Explore"))} <span aria-hidden="true">→</span></span></div>`;
  return `<article class="editorial-panel editorial-panel--${esc(kind)} editorial-panel--${esc(variant)} editorial-panel--media-${panelImageClass(imageValue)}" ${attributes}><a href="${href(route,target)}">${image}${body}</a></article>`;
}
function collaboratorsSection(route,compact=false){const items=(route==="/"?collaborators.filter(item=>item.showOnHomepage!==false):collaborators);if(!items.length)return "";return `<section class="collaborators-section section${compact?" collaborators-section--compact":""}"><div class="collaborators-intro"><p class="overline">Collaborators</p><h2>Heritage work grows through shared effort.</h2></div><ul class="collaborator-list" aria-label="Virsapur collaborators">${items.map(item=>{const content=`<img src="${asset(route,item.logo)}" width="${item.width||320}" height="${item.height||240}" alt="${esc(item.name)}" loading="lazy" decoding="async"><span>${esc(item.name)}</span>`;return `<li>${item.url?`<a href="${esc(item.url)}" rel="noopener noreferrer">${content}</a>`:content}</li>`;}).join("")}</ul></section>`;}
function mapModule(route, full=false) {
  const scripts=["data/world-context.js","assets/maps/pakistan-admin-1.js","data/administrative-snapshot.js","data/regions.js","data/districts.js","data/heritage-places.js","components/heritage-map.js"].map(path=>asset(route,path));
  const related={}; for(const item of [...stories,...projects,...programmes].filter(item=>item.status==="published")) { const key=(item.district||item.practical?.location||"").toLowerCase(); if(!key) continue; related[key] ||= []; related[key].push({type:item.type||"programme",title:item.title,url:href(route,`${item.type==="story"?"/archives":item.type==="project"?"/projects":"/service"}/${item.slug}`),demo:!!item.demo}); }
  const icon=(path)=>`<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">${path}</svg>`;
  const zoomIn=icon('<path d="M12 5v14M5 12h14"/>');
  const zoomOut=icon('<path d="M5 12h14"/>');
  const recenter=icon('<circle cx="12" cy="12" r="5"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/>');
  const overview=icon('<path d="M4 7.5 12 3l8 4.5v9L12 21l-8-4.5z"/><path d="M12 3v18M4 7.5l8 4.5 8-4.5"/>');
  const layers=icon('<path d="m12 3 8 4.5-8 4.5-8-4.5zM4 12l8 4.5 8-4.5M4 16.5l8 4.5 8-4.5"/>');
  const pan=icon('<path d="m12 3 3 3h-2v4h4V8l3 3-3 3v-2h-4v4h2l-3 3-3-3h2v-4H7v2l-3-3 3-3v2h4V6H9z"/>');
  const controls=`<div class="map-controls" aria-label="Map controls"><div class="map-control-rail" role="group" aria-label="Zoom and position"><button type="button" data-map-action="zoom-in" aria-label="Zoom in">${zoomIn}</button><button type="button" data-map-action="zoom-out" aria-label="Zoom out">${zoomOut}</button><button type="button" data-map-action="recenter" aria-label="Recenter current map view">${recenter}</button>${full?`<button type="button" data-map-action="overview" aria-label="Return to Pakistan overview">${overview}</button>`:""}</div>${full?`<details class="map-pan-disclosure"><summary aria-label="Open directional pan controls">${pan}</summary><div class="map-dpad" role="group" aria-label="Pan map"><button type="button" data-map-pan="up" aria-label="Pan up">↑</button><button type="button" data-map-pan="left" aria-label="Pan left">←</button><button type="button" data-map-action="recenter" aria-label="Recenter current map view">•</button><button type="button" data-map-pan="right" aria-label="Pan right">→</button><button type="button" data-map-pan="down" aria-label="Pan down">↓</button></div></details><details class="map-layer-control"><summary aria-label="Map layers">${layers}</summary><div><label><input type="checkbox" data-map-layer="boundaries" checked> Boundaries</label><label><input type="checkbox" data-map-layer="labels" checked> Labels</label></div></details>`:""}</div>`;
  const worldInset=full?`<button class="map-world-inset" type="button" data-map-action="overview" aria-label="Return to the Pakistan overview"><svg viewBox="0 0 1000 500" aria-hidden="true" focusable="false"><path data-world-inset-land></path><path data-world-inset-pakistan></path></svg><span>World context</span></button>`:"";
  return `<section class="map-section${full?" map-section-full":""}${route==="/"?" home-map-section":""}" id="map"><div class="atlas-intro-band"><div class="map-heading"><div><p class="overline">Explore by place</p><h2>Explore Pakistan</h2><p>Discover heritage through its provinces, regions and districts.</p></div>${!full?`<a class="atlas-map-action" href="${href(route,"/heritage-map")}">Explore the full Heritage Atlas <span aria-hidden="true">→</span></a>`:""}</div></div><div class="atlas-stage-shell"><span class="atlas-reference atlas-reference--vertical" aria-hidden="true"></span><span class="atlas-reference atlas-reference--horizontal" aria-hidden="true"></span><div class="map-app" data-heritage-map data-map-variant="${full?"full":"home"}" data-map-scripts='${esc(JSON.stringify(scripts))}'><div class="map-topbar"><nav class="map-crumbs" aria-label="Current map location"></nav><div><span class="layer-name">Country view</span><button class="map-prev" type="button" hidden>Back to Pakistan</button></div></div><div class="map-workspace"><div class="map-stage"><aside class="map-summary" aria-live="polite" aria-atomic="true"></aside><div class="map-load-status" role="status" hidden><p></p><button type="button" hidden>Retry district data</button></div><svg id="pakistan-map" viewBox="0 0 960 720" preserveAspectRatio="xMidYMid meet" role="img" tabindex="0" aria-label="Interactive map of Pakistan’s provinces, regions and districts" aria-describedby="pakistan-map-description"><desc id="pakistan-map-description">Select a region, then a district.</desc><defs><filter id="map-shadow" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="4" stdDeviation="5" flood-color="#30333a" flood-opacity=".11"/></filter></defs><g class="map-world-context" aria-hidden="true" pointer-events="none"><path class="map-world-land" data-world-land></path><path class="map-world-pakistan" data-world-pakistan></path><path class="map-world-pakistan-reference" data-world-pakistan-reference></path><g class="map-world-labels" data-world-labels></g></g><g class="map-vector-viewport"><g class="map-region-paths"></g><g class="map-region-labels"></g></g><g class="map-district-viewport" hidden><path class="map-parent-outline" fill-rule="evenodd" vector-effect="non-scaling-stroke"></path><g class="map-district-paths"></g><g class="map-district-labels" aria-hidden="true"></g><g class="map-heritage-markers"></g></g></svg>${controls}${worldInset}<div class="map-scope"><span>Pakistan → province / region → district</span></div></div>${full?'<aside class="map-heritage-rail" aria-live="polite" aria-label="Heritage in the current map view"></aside>':""}</div><section class="map-heritage-dock" aria-label="Heritage discovery"><button class="map-drawer-toggle" type="button" aria-expanded="false"><span><small>Heritage in this view</small><strong data-heritage-drawer-title>World Heritage</strong></span><b data-heritage-drawer-count>6</b><span data-heritage-drawer-action>Expand ↑</span></button><div class="map-heritage-drawer" hidden><div class="map-heritage-drawer-content"></div><div class="map-district-index"></div></div></section></div><details class="map-methodology"><summary>Map data & methodology</summary><p>Administrative boundaries use the verified Virsapur district dataset. The map stops at district level and preserves stable geographic identifiers.</p><p class="map-world-source">Regional context: Natural Earth 1:110m Admin 0 — Countries, version 5.1.0. Natural Earth and Virsapur’s authoritative Pakistan layer share one regional equirectangular projection and viewport.</p></details></div><script>window.VIRSAPUR_RELATED_CONTENT=${JSON.stringify(related).replace(/</g,"\\u003c")}</script></section>`;
}

function renderBody(blocks,route="/"){if(typeof blocks==="string")return `<p>${esc(blocks)}</p>`;return (blocks||[]).map(b=>{
  if(b.type==="heading")return `${Number(b.level)===3?"<h3>":"<h2>"}${esc(b.text)}${Number(b.level)===3?"</h3>":"</h2>"}`;
  if(b.type==="quote")return `<blockquote><p>“${esc(b.text)}”</p>${b.attribution?`<footer>${esc(b.attribution)}</footer>`:""}</blockquote>`;
  if(b.type==="callout")return `<aside class="story-callout">${b.title?`<strong>${esc(b.title)}</strong>`:""}<p>${esc(b.text)}</p></aside>`;
  if(b.type==="image"){const src=b.src||b.image?.src||"";return /^https?:\/\//.test(src)?`<figure><img src="${esc(src)}" alt="${esc(b.alt||b.image?.alt||"")}" loading="lazy">${b.caption?`<figcaption>${esc(b.caption)}</figcaption>`:""}</figure>`:picture(route,{src,alt:b.alt||"",width:b.width||1280,height:b.height||720});}
  if(b.type==="gallery")return `<div class="story-gallery">${(b.images||[]).map(image=>{const src=typeof image==="string"?image:image.src;const alt=typeof image==="string"?"":image.alt||"";return /^https?:\/\//.test(src)?`<img src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`:picture(route,{src,alt,width:image.width||1280,height:image.height||720});}).join("")}</div>`;
  if(b.type==="embed"&&/^https:\/\//.test(b.url||""))return `<div class="story-embed"><iframe src="${esc(b.url)}" title="${esc(b.title||"Embedded content")}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>`;
  return `<p>${esc(b.text||"")}</p>`;
}).join("");}
function eventSchema(event){return {"@type":"Event",name:event.title,startDate:event.start,endDate:event.end,eventStatus:"https://schema.org/EventScheduled",location:{"@type":"Place",name:event.location},organizer:{"@type":"Organization",name:site.name,url:siteOrigin},isAccessibleForFree:event.commerce?.amount===0,description:event.summary,url:canonical(`/whats-on#${event.slug}`)};}
function eventCard(route,item,{enquiryOnly=false}={}){const start=new Date(item.start);const day=start.toLocaleDateString("en-PK",{day:"2-digit"});const month=start.toLocaleDateString("en-PK",{month:"short"}).toUpperCase();const time=start.toLocaleTimeString("en-PK",{hour:"numeric",minute:"2-digit"});const action=!enquiryOnly&&studioMode&&item.commerce?.enabled?`<button class="button" data-checkout data-event-id="${item.id}" data-title="${esc(item.title)}" data-amount="${item.commerce.amount||0}">${esc(item.commerce.label||"Open demo checkout")}</button>`:`<a class="editorial-panel-action" href="${href(route,"/contact?type=programme")}">Enquire <span aria-hidden="true">→</span></a>`;const imageValue=recordVisualImage(item);return `<article class="editorial-panel editorial-panel--event editorial-panel--portrait editorial-panel--media-${panelImageClass(imageValue)}" id="${esc(item.slug)}" data-record data-title="${esc(item.title.toLowerCase())}" data-type="occurrence" data-location="${esc(item.location.toLowerCase())}" data-month="${esc(String(item.start).slice(0,7))}">${picture(route,imageValue,{className:"editorial-panel-image",sizes:"(max-width:700px) 86vw,(max-width:1000px) 44vw,30vw"})}<div class="editorial-panel-body">${badge(item)}<div class="event-date-lockup"><time datetime="${esc(item.start)}"><strong>${esc(day)}</strong><span>${esc(month)}</span></time><p>${esc(time)}<br>${esc(item.location)}</p></div><p class="overline event-type">${esc(item.type||"Event")}</p><h3>${esc(item.title)}</h3><p class="editorial-panel-summary">${esc(item.summary)}</p><p class="editorial-panel-facts">${esc(item.registrationState)}</p>${action}</div></article>`;}

const {districts:districtMetadata,regions:regionMetadata}=await loadHeritageContext(root);
const heritageImageDimensions=await loadHeritageImageDimensions(root,heritagePlaces);
const heritagePages = createHeritagePages({places:heritagePlaces,collections:{stories,programmes,projects,events},districts:districtMetadata,regions:regionMetadata,imageDimensions:heritageImageDimensions,preview:studioMode,esc,href,asset,canonical,shell,crumbs,editorialPanel,eventCard});
const searchIndex = searchableRecords({stories,projects,programmes,events,places:heritagePages.eligible},heritagePages.locationText);
function homePage(){const route="/";const curated=(records,ids)=>{const selected=selectByIds(records,ids);return selected.length?selected:records.filter(item=>item.status==="published").sort((a,b)=>(a.sortOrder??999)-(b.sortOrder??999));};const current=curated(events,homepage.current?.eventIds);const storyCards=curated(stories,homepage.stories?.storyIds);const projectCards=curated(projects,homepage.projects?.projectIds);const featuredProgrammes=curated(programmes,homepage.experiences?.programmeIds);const homepageCategories=archiveCategories.filter(item=>item.showOnHomepage).sort((a,b)=>(a.homepageOrder??a.sortOrder??999)-(b.homepageOrder??b.sortOrder??999));const render={
  hero:()=>`<section class="discovery-hero"><div class="discovery-hero-media">${picture(route,visualImage("homepage.hero",homepage.hero.image),{eager:true,sizes:"100vw"})}</div><div class="discovery-hero-shade"></div><div class="discovery-hero-content"><p class="overline">${esc(homepage.hero.eyebrow)}</p><h1>${esc(homepage.hero.title)}</h1><p>${esc(homepage.hero.summary)}</p><div class="hero-actions">${homepage.hero.actions.map(a=>`<a class="button ${a.style}" href="${href(route,a.route)}">${esc(a.label)} <span>→</span></a>`).join("")}</div></div><p class="hero-place">${esc(visualImage("homepage.hero",homepage.hero.image).caption)}</p></section>`,
  quickDiscovery:()=>`<section class="quick-discovery discovery-shelf" aria-label="Explore Virsapur">${homepage.quickDiscovery.map(i=>`<a href="${href(route,i.route)}"><small>${esc(i.eyebrow)}</small><span class="discovery-shelf-path"><strong>${esc(i.title)}</strong><span class="discovery-shelf-action">Explore <span aria-hidden="true">→</span></span></span></a>`).join("")}</section>`,
  current:()=>current.length?`<section class="home-current section"><div class="home-section-intro"><p class="overline">${esc(homepage.current?.eyebrow||"What’s happening")}</p><h2>${esc(homepage.current?.title||"See what’s happening with Virsapur.")}</h2></div><div class="editorial-panel-grid editorial-panel-grid--events">${current.map(item=>eventCard(route,item)).join("")}</div></section>`:"",
  map:()=>mapModule(route),
  experiences:()=>featuredProgrammes.length?`<section class="home-experiences section"><div class="home-section-intro"><div><p class="overline">${esc(homepage.experiences.eyebrow)}</p><h2>${esc(homepage.experiences.title)}</h2></div><p>${esc(homepage.experiences.summary)}</p></div><div class="editorial-panel-grid editorial-panel-grid--programmes">${featuredProgrammes.map(i=>editorialPanel(route,{...i,kind:homepage.experiences.categoryLabels?.[i.id]||i.kind},{kind:"programme",variant:"documentary"})).join("")}</div></section>`:"",
  stories:()=>storyCards.length?`<section class="home-stories section"><div class="home-section-intro"><div><p class="overline">${esc(homepage.stories.eyebrow)}</p><h2>${esc(homepage.stories.title)}</h2></div><a class="text-action" href="${href(route,homepage.stories.cta?.route||"/archives")}">${esc(homepage.stories.cta?.label||"Explore all stories")} →</a></div><div class="editorial-panel-grid editorial-panel-grid--stories">${storyCards.map(i=>editorialPanel(route,i,{kind:"story",variant:"portrait"})).join("")}</div></section>`:"",
  projects:()=>projectCards.length?`<section class="home-projects section"><div class="home-section-intro"><div><p class="overline">${esc(homepage.projects.eyebrow)}</p><h2>${esc(homepage.projects.title)}</h2></div><a class="text-action" href="${href(route,homepage.projects.cta?.route||"/our-work")}">${esc(homepage.projects.cta?.label||"Explore our work")} →</a></div><div class="editorial-panel-grid editorial-panel-grid--projects">${projectCards.map(i=>editorialPanel(route,i,{kind:"project",variant:"documentary"})).join("")}</div></section>`:"",
  themes:()=>homepageCategories.length?`<section class="theme-band theme-index section"><p class="overline">${esc(homepage.themes.eyebrow)}</p><h2>${esc(homepage.themes.title)}</h2><div>${homepageCategories.map(i=>`<a href="${href(route,`/archives/category/${i.slug}`)}"><span class="theme-index-copy"><strong>${esc(i.shortTitle||i.title)}</strong>${i.summary?`<small>${esc(i.summary)}</small>`:""}</span><span class="theme-index-action">Explore <span aria-hidden="true">→</span></span></a>`).join("")}</div></section>`:"",
  mission:()=>`<section class="home-purpose section"><div class="home-purpose-statement"><p class="overline">Purpose</p><h2>${esc(site.purpose)}</h2></div><div class="home-purpose-notes"><article><h3>Mission</h3><p>${esc(site.mission)}</p></article><article><h3>Vision</h3><p>${esc(site.vision)}</p></article></div></section>`,
  about:()=>`<section class="home-about"><div class="about-mosaic">${picture(route,visualImage("homepage.about.primary",homepage.about.images[0]),{className:"about-image-primary",sizes:"(max-width:760px) 64vw,34vw"})}${picture(route,visualImage("homepage.about.support",homepage.about.images[1]),{className:"about-image-support",sizes:"(max-width:760px) 36vw,20vw"})}</div><div class="about-home-copy"><p class="overline">About Virsapur</p><h2>${esc(homepage.about.title)}</h2><p>${esc(homepage.about.summary)}</p><a class="text-action light-action" href="${href(route,"/why-virsapur")}">Meet Virsapur →</a></div></section>`,
  collaborators:()=>collaboratorsSection(route),
  finalAction:()=>`<section class="home-closing"><div class="home-final-intro section"><p class="overline">${esc(homepage.finalAction.eyebrow)}</p><p>${esc(homepage.finalAction.summary)}</p></div><div class="home-final-action">${picture(route,visualImage("homepage.final-action",homepage.finalAction.image),{decorative:true})}<span class="final-action-shade"></span><div><h2>${esc(homepage.finalAction.title)}</h2><div>${homepage.finalAction.actions.map(a=>`<a class="button ${a.style}" href="${href(route,a.route)}">${esc(a.label)} →</a>`).join("")}</div></div></div></section>`};
  return shell({route,active:"home",title:homepage.seo.title,description:homepage.seo.description,image:homepage.hero.image,main:homepage.modules.filter(module=>module.enabled).map(module=>render[module.type]?.()||"").join(""),schema:[{"@type":"WebSite","@id":`${siteOrigin}/#website`,name:site.name,url:`${siteOrigin}/`,potentialAction:{"@type":"SearchAction",target:`${siteOrigin}/search?q={search_term_string}`,"query-input":"required name=search_term_string"}},{"@type":"Organization","@id":`${siteOrigin}/#organization`,name:site.name,url:`${siteOrigin}/`,email:site.email,telephone:site.phone}]}); }

function programmesPage(){const route="/programmes";return shell({route,active:"programmes",title:"Experiences and Programmes | Virsapur",description:"Explore Virsapur heritage experiences, learning, research and cultural collaborations.",main:pageHero(route,{eyebrow:"Experiences",title:"Discover Virsapur programmes.",intro:"Designed to help people encounter, learn about and engage with heritage.",variant:"functional"})+`<section class="section programme-catalogue"><div class="editorial-panel-grid editorial-panel-grid--programmes">${programmes.map(i=>editorialPanel(route,i,{kind:"programme",variant:"documentary"})).join("")}</div></section>`+cta(route)});}
function programmePage(item){const route=`/service/${item.slug}`;const cr=crumbs(route,[{label:"Home",path:"/"},{label:"Experiences",path:"/programmes"},{label:item.title}]);const occurrences=events.filter(e=>e.programmeId===item.id);const facts=Object.entries(item.practical||{}).filter(([,v])=>v).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join("");const schedule=occurrences.length?`<section class="section"><div class="section-heading"><p class="overline">Schedule</p><h2>Upcoming dates</h2></div><div class="editorial-panel-grid editorial-panel-grid--events">${occurrences.map(event=>eventCard(route,event)).join("")}</div></section>`:"";const practical=facts?`<section class="programme-practical section"><p class="overline">Practical information</p><dl class="fact-grid">${facts}</dl></section>`:"";return shell({route,active:"programmes",title:item.seo.title,description:item.seo.description,image:item.featuredImage,status:item.status,schema:[cr.schema,...occurrences.map(eventSchema)],main:cr.html+`<section class="programme-opening section"><div><p class="overline">${esc(item.kind||"Programme")}</p><h1>${esc(item.title)}</h1><p class="programme-proposition">${esc(item.summary)}</p><a class="button primary" href="${href(route,item.cta.target)}">${esc(item.cta.label)} <span>→</span></a></div>${picture(route,recordVisualImage(item),{className:"programme-opening-image",eager:true,sizes:"(max-width:820px) 100vw,52vw"})}</section>`+practical+`<section class="programme-detail section"><div><p class="overline">Overview</p><h2>${esc(item.summary)}</h2></div><div class="prose">${renderBody(item.body,route)}</div></section>`+schedule+heritagePages.placeModule(route,item,"Places on this experience")+heritagePages.programmeStories(route,item)});}
function whatsOnPage(){const route="/whats-on";const months=[...new Set(events.map(item=>String(item.start).slice(0,7)))];return shell({route,active:"whats-on",title:"What’s On | Virsapur",description:"Upcoming Virsapur heritage experiences, workshops and cultural activities.",main:pageHero(route,{eyebrow:"Schedule",title:"What’s on",intro:"Upcoming Virsapur experiences, learning and cultural activities.",variant:"functional"})+`<section class="collection-tools section"><div class="filters filters--whats-on"><label>Search<input type="search" data-collection-search></label><label>Type<select data-filter="type"><option value="">All activities</option><option value="occurrence">Activities</option></select></label><label>Month<select data-filter="month"><option value="">All months</option>${months.map(month=>`<option value="${month}">${new Date(`${month}-01T00:00:00`).toLocaleDateString("en-PK",{month:"long",year:"numeric"})}</option>`).join("")}</select></label><label>Location<input data-filter="location" placeholder="Place or online"></label></div><p data-collection-count>${events.length} activities</p><div class="editorial-panel-grid editorial-panel-grid--events" data-collection>${events.map(e=>eventCard(route,e)).join("")}</div></section><dialog class="checkout-dialog" data-checkout-dialog><form method="dialog"><button class="dialog-close" value="cancel" aria-label="Close">×</button><p class="overline">Studio mock commerce</p><h2 data-checkout-title>Demo checkout</h2><div class="demo-warning">DEMO ONLY · No real payment is processed. Do not enter card or bank details.</div><label>Quantity<input type="number" min="1" max="10" value="1" data-checkout-qty></label><label>Test customer<input value="Demo Visitor" data-checkout-name></label><p>Total: <strong data-checkout-total>PKR 0</strong></p><div class="checkout-actions"><button class="button" value="success" data-checkout-result="success">Simulate success</button><button value="declined" data-checkout-result="declined">Simulate decline</button><button value="cancelled" data-checkout-result="cancelled">Simulate cancellation</button></div><p aria-live="polite" data-checkout-message></p></form></dialog>`});}
function archiveCategoryPanel(route,item){const count=stories.filter(story=>story.status==="published"&&(story.categoryIds||[]).includes(item.id)).length;return `<article class="archive-category-panel">${picture(route,item.featuredImage,{className:"archive-category-panel-image",sizes:"(max-width:620px) 92vw,(max-width:980px) 46vw,30vw"})}<a href="${href(route,`/archives/category/${item.slug}`)}" aria-label="Explore ${esc(item.title)}"><span class="archive-category-panel-shade"></span><div>${badge(item)}<h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><small>${count} ${count===1?"story":"stories"}</small><strong>Explore <span aria-hidden="true">→</span></strong></div></a></article>`;}
function archivesPage(){const route="/archives";const highlights=stories.filter(item=>item.status==="published"&&item.featured);const featured=highlights.length?`<section class="archive-featured section"><div class="home-section-intro"><div><p class="overline">From the archive</p><h2>Featured and recently added stories</h2></div><a class="text-action" href="${href(route,"/archives/all")}">Browse all stories →</a></div><div class="editorial-panel-grid editorial-panel-grid--stories">${highlights.map(item=>editorialPanel(route,item,{kind:"story",variant:"portrait"})).join("")}</div></section>`:"";const categories=archiveCategories.length?`<section class="archive-categories section"><div class="archive-collections-heading"><p class="overline">Explore the collections</p><h2>Follow heritage through connected fields of inquiry.</h2></div><div class="archive-category-grid">${archiveCategories.map(item=>archiveCategoryPanel(route,item)).join("")}</div></section>`:"";const search=`<section class="archive-global-search section"><form action="${href(route,"/archives/all")}" method="get"><label for="archive-discovery-search">Search the Archive</label><div><input id="archive-discovery-search" name="q" type="search" placeholder="Search places, objects, people or traditions"><button class="button primary">Search <span aria-hidden="true">→</span></button></div></form></section>`;return shell({route,active:"archives",title:"Archives | Virsapur",description:"Explore Virsapur’s curated Archive collections and researched stories about Pakistan’s heritage.",image:archiveCategories[0]?.featuredImage||"assets/archive-architecture.webp",main:pageHero(route,{eyebrow:"Places · objects · cultural memory",title:"Stories & Archives",intro:"Explore researched stories through collections that connect place, material culture and living memory.",variant:"functional"})+search+categories+featured+`<section class="archive-browse-callout section"><p class="overline">Complete collection</p><h2>Looking for a specific place, object or story?</h2><a class="button primary" href="${href(route,"/archives/all")}">Browse all stories <span aria-hidden="true">→</span></a></section>`});}
function archivesAllPage(){const route="/archives/all";const provinces=[...new Set(stories.map(i=>i.province).filter(Boolean))].sort();const collection=stories.length?`<section class="collection-tools archive-collection section"><form class="filters filters--archive" data-collection-filters><label>Keyword<input name="q" type="search" data-collection-search></label><label>Category<select name="category" data-filter="category"><option value="">All categories</option>${archiveCategories.map(item=>`<option value="${esc(item.id)}">${esc(item.shortTitle||item.title)}</option>`).join("")}</select></label><label>Province<select name="province" data-filter="province"><option value="">All provinces</option>${provinces.map(v=>`<option>${esc(v)}</option>`).join("")}</select></label><label>District<input name="district" data-filter="district"></label><label>Type<select name="type" data-filter="type"><option value="">All types</option><option value="story">Story</option></select></label><button class="filter-reset" type="reset">Clear filters</button></form><div class="archive-result-line"><p data-collection-count>${stories.length} stories</p><span>Browse researched places, objects and cultural memory</span></div><div class="editorial-panel-grid editorial-panel-grid--stories archive-collection-grid" data-collection>${stories.map(i=>editorialPanel(route,i,{kind:"story",variant:"portrait"})).join("")}</div><nav class="pagination" aria-label="Archive pages" data-pagination></nav></section>`:`<section class="archive-empty section"><div><p class="overline">Collection in progress</p><h2>Researched stories will appear here as they are published.</h2></div><div><p>Return to the curated Archive collections while the database grows.</p><a class="button" href="${href(route,"/archives")}">Explore Archive collections <span>→</span></a></div></section>`;return shell({route,active:"archives",title:"Browse All Stories | Virsapur Archives",description:"Search and filter the complete Virsapur Archive by category, province, district and type.",image:archiveCategories[0]?.featuredImage||"assets/archive-architecture.webp",main:crumbs(route,[{label:"Home",path:"/"},{label:"Archives",path:"/archives"},{label:"Browse all stories"}]).html+pageHero(route,{eyebrow:"Archive database",title:"Browse all stories",intro:"Search and filter the complete Virsapur story collection.",variant:"functional"})+collection});}
function archiveCategoryPage(item){const route=`/archives/category/${item.slug}`;const categoryStories=stories.filter(story=>(story.categoryIds||[]).includes(item.id));const cr=crumbs(route,[{label:"Home",path:"/"},{label:"Archives",path:"/archives"},{label:item.title}]);const collection=categoryStories.length?`<section class="archive-category-stories section"><div class="archive-result-line"><p>${categoryStories.length} ${categoryStories.length===1?"story":"stories"}</p><span>Published records connected to this collection</span></div><div class="editorial-panel-grid editorial-panel-grid--stories">${categoryStories.map(story=>editorialPanel(route,story,{kind:"story",variant:"portrait"})).join("")}</div></section>`:`<section class="archive-empty section"><div><p class="overline">Collection in progress</p><h2>No stories are assigned to this collection yet.</h2></div><a class="text-action" href="${href(route,"/archives/all")}">Browse all stories →</a></section>`;return shell({route,active:"archives",status:item.status,title:item.seo.title,description:item.seo.description,image:item.featuredImage,schema:[cr.schema,{"@type":"CollectionPage",name:item.title,description:item.description,url:canonical(route)}],main:cr.html+pageHero(route,{eyebrow:"Archive collection",title:item.title,intro:item.description,image:item.featuredImage,variant:"editorial"})+collection});}
function relatedSection(route,item){const ids=new Set([...(item.relatedStoryIds||[]),...(item.relatedProjectIds||[]),...(item.relatedProgrammeIds||[])]);const all=[...stories,...projects,...programmes].filter(i=>ids.has(i.id));return all.length?`<aside class="related-content section"><p class="overline">Continue exploring</p><h2>Related content</h2><div class="editorial-panel-grid editorial-panel-grid--related">${all.map(i=>editorialPanel(route,i,{kind:i.type||"programme",variant:"compact"})).join("")}</div></aside>`:"";}
function storyPage(item){const route=`/archives/${item.slug}`;const category=primaryCategory(item);const cr=crumbs(route,[{label:"Home",path:"/"},{label:"Archives",path:"/archives"},{label:item.title}]);return shell({route,active:"archives",status:item.status,title:item.seo.title,description:item.seo.description,image:item.featuredImage,schema:[cr.schema,{"@type":"Article",headline:item.title,description:item.summary,image:absoluteImage(item.featuredImage),articleSection:storyCategoryLabel(item),author:item.author?{"@type":"Person",name:item.author}:undefined,datePublished:item.publishedAt||undefined}],main:cr.html+`<article class="story-longform"><header>${badge(item)}<p class="overline">${category?`<a href="${href(route,`/archives/category/${category.slug}`)}">${esc(category.title)}</a>`:esc(item.category)}${item.location?` · ${esc(item.location)}`:""}</p><h1>${esc(item.title)}</h1><p class="standfirst">${esc(item.summary)}</p>${item.author?`<p>By ${esc(item.author)}${item.publishedAt?` · ${esc(item.publishedAt)}`:""}</p>`:""}</header>${picture(route,recordVisualImage(item),{className:"story-image",eager:true,sizes:"100vw"})}<div class="story-body">${renderBody(item.body,route)}${item.references?.length?`<h2>References</h2><ol>${item.references.map(r=>`<li>${esc(r)}</li>`).join("")}</ol>`:""}</div></article>`+relatedSection(route,item)+heritagePages.placeModule(route,item,"Places in this story")});}
function ourWorkPage(){const route="/our-work";const pathways=`<ul class="work-pathways" aria-label="Areas of work"><li>Research</li><li>Documentation</li><li>Preservation</li><li>Public engagement</li></ul>`;const opening=`<section class="work-opening section"><div class="work-opening-copy"><p class="overline">Research · documentation · preservation</p><h1>Our work</h1><p>Careful cultural work connecting evidence, place and public understanding.</p>${pathways}</div>${picture(route,visualImage("our-work.opening","assets/project-1.png"),{className:"work-opening-image",eager:true,sizes:"(max-width:820px) 100vw,56vw"})}</section>`;const method=`<section class="work-method work-method--ink section"><div class="work-method-copy"><p class="overline">How we work</p><h2>Research first. Interpret clearly. Collaborate with care.</h2><p>Virsapur’s institutional work brings together documentation, cultural learning and public-facing interpretation.</p><a class="text-action light-action" href="${href(route,"/service/research-and-restoration-projects")}">Research & restoration programme →</a></div>${picture(route,visualImage("our-work.method","assets/temple_angle.jpg"),{className:"work-method-image",sizes:"(max-width:820px) 100vw,31vw"})}</section>`;return shell({route,active:"work",title:"Our Work | Virsapur",description:"Explore Virsapur’s approach to research, documentation, preservation and public engagement.",main:opening+method+`${projects.length?`<section class="work-projects section"><div class="section-heading"><p class="overline">Project records</p><h2>Selected projects</h2></div><div class="editorial-panel-grid editorial-panel-grid--projects">${projects.map(i=>editorialPanel(route,i,{kind:"project",variant:"documentary"})).join("")}</div></section>`:""}`+cta(route,"Discuss a research or preservation project.")});}
function projectPage(item){const route=`/projects/${item.slug}`;const cr=crumbs(route,[{label:"Home",path:"/"},{label:"Our work",path:"/our-work"},{label:item.title}]);return shell({route,active:"work",status:item.status,title:item.seo.title,description:item.seo.description,image:item.featuredImage,schema:[cr.schema],main:cr.html+pageHero(route,{eyebrow:"Project case study",title:item.title,intro:item.summary,image:recordVisualImage(item)})+`<section class="project-case section"><div class="prose">${renderBody(item.body,route)}</div><dl class="case-facts">${item.location?`<div><dt>Location</dt><dd>${esc(item.location)}</dd></div>`:""}${item.dates?.start?`<div><dt>Dates</dt><dd>${esc(item.dates.start)}${item.dates.end?`–${esc(item.dates.end)}`:""}</dd></div>`:""}${item.partners?.length?`<div><dt>Partners</dt><dd>${item.partners.map(esc).join(", ")}</dd></div>`:""}</dl>${item.outcomes?.length?`<div><p class="overline">Outcomes</p><ul>${item.outcomes.map(i=>`<li>${esc(i)}</li>`).join("")}</ul></div>`:""}</section>`+relatedSection(route,item)+heritagePages.placeModule(route,item,"Heritage connected to this project")+cta(route)});}
function aboutPage(){const route="/why-virsapur";const curatedProjects=selectByIds(projects,homepage.projects?.projectIds);const evidenceProjects=curatedProjects.length?curatedProjects:projects;const evidence=evidenceProjects.length?`<section class="why-evidence section"><div class="section-heading"><p class="overline">Work in practice</p><h2>Research and preservation records</h2></div><div class="editorial-panel-grid editorial-panel-grid--projects">${evidenceProjects.map(i=>editorialPanel(route,i,{kind:"project",variant:"compact"})).join("")}</div></section>`:"";return shell({route,active:"about",title:"Why Virsapur | Purpose, mission and people",description:"Learn about Virsapur’s purpose, mission, vision, people and approach to Pakistan’s heritage.",image:"assets/fresco_room.jpg",main:pageHero(route,{eyebrow:"Purpose · people · preservation",title:"Why Virsapur?",intro:"Making Pakistan’s heritage visible, understandable and worth protecting.",image:visualImage("why.hero","assets/fresco_room.jpg"),variant:"editorial"})+`<section class="why-purpose section"><p class="overline">Our purpose</p><h2>${esc(site.purpose)}</h2></section><section class="mission-vision section"><div><p class="overline">Direction</p><h2>Mission and vision</h2></div><div><h3>Mission</h3><p>${esc(site.mission)}</p><h3>Vision</h3><p>${esc(site.vision)}</p></div></section><section class="why-people section"><div class="section-heading"><p class="overline">People</p><h2>Virsapur’s founders</h2></div><div class="founder-grid">${people.map(p=>`<article>${picture(route,p.image)}<div><p class="overline">${esc(p.role)}</p><h3>${esc(p.name)}</h3><p>${esc(p.biography)}</p></div></article>`).join("")}</div></section><section class="why-approach section"><div class="why-approach-copy"><p class="overline">How we work</p><h2>${esc(homepage.about.title)}</h2><p>${esc(homepage.about.summary)}</p></div><div class="why-approach-images">${picture(route,visualImage("why.approach.primary",homepage.about.images[1]),{className:"why-approach-primary",sizes:"(max-width:760px) 64vw,32vw"})}${picture(route,visualImage("why.approach.support",homepage.about.images[2]),{className:"why-approach-support",sizes:"(max-width:760px) 36vw,22vw"})}</div></section>${evidence}${collaboratorsSection(route,true)}`+cta(route)});}
function heritageMapPage(){const route="/heritage-map";return shell({route,active:"map",title:"Heritage Map of Pakistan | Virsapur",description:"Explore Virsapur’s interactive Heritage Map of Pakistan across provinces, regions and districts.",main:`<section class="atlas-page-intro section"><p class="overline">Interactive Heritage Atlas</p><div><h1>Explore Pakistan</h1><p>Country <span aria-hidden="true">→</span> Province <span aria-hidden="true">→</span> District</p></div></section>`+mapModule(route,true)+cta(route)});}
function searchPage(){const route="/search";const index=searchIndex;return shell({route,title:"Search | Virsapur",description:"Search Virsapur heritage places, stories, programmes, projects and activities.",main:pageHero(route,{eyebrow:"Across Virsapur",title:"Search",intro:"Find heritage places, stories, experiences, projects and activities.",variant:"functional"})+`<section class="search-page section"><label for="site-search">Search Virsapur</label><input id="site-search" type="search" data-site-search autofocus><p data-search-count>Enter a word or phrase.</p><div data-search-results></div><script type="application/json" id="search-index">${JSON.stringify(index).replace(/</g,"\\u003c")}</script></section>`});}
function contactPage(){const route="/contact";return shell({route,active:"contact",title:"Contact Virsapur",description:"Contact Virsapur about heritage experiences, education, research, media or collaboration.",main:`<section class="contact-page contact-composition section"><div class="contact-intro"><p class="overline">Get in touch</p><h1>Start a conversation about heritage.</h1><p class="contact-standfirst">Choose the kind of enquiry and tell Virsapur what you have in mind.</p><div class="contact-details"><p><strong>${esc(site.name)}</strong></p><p><a href="mailto:${esc(site.email)}">${esc(site.email)}</a></p>${site.phone?`<p><a href="tel:${phoneHref}">${esc(site.phone)}</a></p>`:""}</div></div><form data-contact-form novalidate><label>Name<input name="name" required autocomplete="name"></label><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Enquiry type<select name="type"><option>General</option><option>Programme or experience</option><option>Research or project</option><option>Education</option><option>Media</option><option>Partnership</option></select></label><label>Message<textarea name="message" rows="6" required></textarea></label><button class="button" type="submit">Send enquiry</button><p class="form-note" data-form-note aria-live="polite">Online submission is not connected. Your message will not be sent by this form.</p></form></section>`});}
function redirectPage(route,target,label){const targetHref=href(route,target);return `<!doctype html><html><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><link rel="canonical" href="${canonical(target)}"><meta http-equiv="refresh" content="0;url=${targetHref}"><title>${esc(label)}</title></head><body><a href="${targetHref}">Continue</a></body></html>`;}
function notFound(){const route="/404";return shell({route,status:"archived",title:"Page not found | Virsapur",description:"The requested Virsapur page could not be found.",main:`<section class="not-found"><p class="overline">404</p><h1>This path doesn’t lead to a Virsapur page.</h1><p><a href="${href(route,"/")}">Return home</a></p></section>`});}

async function writeRoute(route,html,options={}){const file=route==="/"?join(outputRoot,"index.html"):join(outputRoot,route.slice(1),"index.html");await mkdir(dirname(file),{recursive:true});await writeFile(file,html,"utf8");routeManifest.push({route,status:options.status||"published",indexable:!studioMode&&(options.status||"published")==="published"&&!options.redirectTo,sitemap:!studioMode&&(options.status||"published")==="published"&&!options.redirectTo,type:options.type||"page",redirectTo:options.redirectTo||null});}
await writeRoute("/",homePage());
await writeRoute("/home",redirectPage("/home","/","Virsapur home"),{status:"archived",redirectTo:"/"});
await writeRoute("/why-virsapur",aboutPage()); await writeRoute("/programmes",programmesPage()); await writeRoute("/heritage-map",heritageMapPage()); await writeRoute("/archives",archivesPage()); await writeRoute("/archives/all",archivesAllPage(),{type:"collection"}); await writeRoute("/our-work",ourWorkPage()); await writeRoute("/search",searchPage()); await writeRoute("/contact",contactPage());
if(events.length) await writeRoute("/whats-on",whatsOnPage(),{type:"collection"});
for(const item of programmes){await writeRoute(`/service/${item.slug}`,programmePage(item),{status:item.status,type:"programme"});if(item.legacySlug)await writeRoute(`/service/${item.legacySlug}`,redirectPage(`/service/${item.legacySlug}`,`/service/${item.slug}`,item.title),{status:"archived",redirectTo:`/service/${item.slug}`});}
for(const item of heritagePages.eligible)await writeRoute(heritagePath(item),heritagePages.page(item),{status:item.status,type:"heritage-place"});
for(const item of stories)await writeRoute(`/archives/${item.slug}`,storyPage(item),{status:item.status,type:"story"});
for(const item of archiveCategories)await writeRoute(`/archives/category/${item.slug}`,archiveCategoryPage(item),{status:item.status,type:"archive-category"});
for(const item of projects)await writeRoute(`/projects/${item.slug}`,projectPage(item),{status:item.status,type:"project"});
for(const entry of [...storiesBase,...projectsBase,...programmesBase].flatMap(item=>(item.previousSlugs||[]).map(slug=>({slug,item})))){const base=entry.item.type==="story"?"archives":entry.item.type==="project"?"projects":"service";await writeRoute(`/${base}/${entry.slug}`,redirectPage(`/${base}/${entry.slug}`,`/${base}/${entry.item.slug}`,entry.item.title),{status:"archived",redirectTo:`/${base}/${entry.item.slug}`});}
await writeRoute("/404",notFound(),{status:"archived",type:"utility"});

const sitemapRoutes=routeManifest.filter(i=>i.sitemap&&i.indexable).map(i=>i.route);
await writeFile(join(outputRoot,"sitemap.xml"),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${sitemapRoutes.map(r=>`<url><loc>${canonical(r)}</loc></url>`).join("")}</urlset>\n`);
await writeFile(join(outputRoot,"robots.txt"),studioMode?"User-agent: *\nDisallow: /\n":`User-agent: *\nAllow: /\nSitemap: ${siteOrigin}/sitemap.xml\n`);
await writeFile(join(outputRoot,"route-manifest.json"),JSON.stringify({generatedAt:new Date().toISOString(),mode,siteOrigin,routes:routeManifest},null,2)+"\n");
await writeFile(join(outputRoot,"search-index.json"),JSON.stringify(searchIndex,null,2)+"\n");
await writeFile(join(outputRoot,"404.html"),notFound().replaceAll("../",""));
await mkdir(join(outputRoot,"assets","maps"),{recursive:true}); await mkdir(join(outputRoot,"components"),{recursive:true}); await mkdir(join(outputRoot,"data"),{recursive:true});
await cp(join(root,"assets","optimized"),join(outputRoot,"assets","optimized"),{recursive:true}); await cp(join(root,"assets","collaborators"),join(outputRoot,"assets","collaborators"),{recursive:true}); await cp(join(root,"assets","maps","pakistan-admin-1.js"),join(outputRoot,"assets","maps","pakistan-admin-1.js")); await cp(join(root,"assets","maps","runtime"),join(outputRoot,"assets","maps","runtime"),{recursive:true}); await cp(join(root,"components","heritage-map.js"),join(outputRoot,"components","heritage-map.js")); for(const file of ["world-context.js","administrative-snapshot.js","regions.js","districts.js"])await cp(join(root,"data",file),join(outputRoot,"data",file)); await writeFile(join(outputRoot,"data","heritage-places.js"),`window.VIRSAPUR_ATLAS_SCOPE_MEDIA=${JSON.stringify(atlasScopeMedia)};\nwindow.VIRSAPUR_HERITAGE_PLACES=${JSON.stringify(heritagePlaces.map(record=>({...record,...(isEligibleHeritagePlace(record)?{detailsPagePath:heritagePath(record)}:{})}))).replace(/</g,"\\u003c")};\nwindow.VIRSAPUR_HERITAGE_ASSIGNMENT_FAILURES=${JSON.stringify(preparedHeritage.failures)};\n`);
const baseCss=await readFile(join(root,"styles.css"),"utf8"); const platformCss=await readFile(join(root,"src","platform.css"),"utf8"); const atlasCss=await readFile(join(root,"src","atlas-interface.css"),"utf8"); await writeFile(join(outputRoot,"styles.css"),`${baseCss}\n${platformCss}\n${atlasCss}\n${await readFile(join(root,"src","heritage-connections.css"),"utf8")}`); await cp(join(root,"app.js"),join(outputRoot,"app.js"));
if(!studioMode && isProductionCmsEnabled()){
  await mkdir(join(outputRoot,"admin","login"),{recursive:true});
  const adminHtml=(await readFile(join(root,"studio","index.html"),"utf8")).replace('href="studio.css"','href="admin.css"').replace('src="studio.js"','src="admin.js"').replace('data-site-link href="/"','data-site-link href="../index.html"');
  const loginHtml=(await readFile(join(root,"studio","login.html"),"utf8")).replace('href="../studio.css"','href="../admin.css"');
  await writeFile(join(outputRoot,"admin","index.html"),adminHtml);
  await cp(join(root,"studio","studio.css"),join(outputRoot,"admin","admin.css"));
  await cp(join(root,"studio","studio.js"),join(outputRoot,"admin","admin.js"));
  await writeFile(join(outputRoot,"admin","login","index.html"),loginHtml);
  await cp(join(root,"studio","login.js"),join(outputRoot,"admin","login.js"));
}
console.log(`Built ${routeManifest.length} ${mode} routes (${sitemapRoutes.length} indexable) in ${outputRoot}.`);
